// Claude's review tests for A39 (add or change request headers on real calls). agy: do not edit this file.
import { describe, expect, it } from 'vitest';
import { exportProject, parseProjectFile } from './exportFile';
import { applyHeaderRules, forbiddenHeaderReason, rulesFor } from './headerRules';
import { mergeProject, replaceProject } from './scenarioOps';
import { newProject, type HeaderRule } from './types';

const rule = (id: string, extra: Partial<HeaderRule> = {}): HeaderRule => ({
  id, enabled: true, method: 'ANY', urlPattern: '/api/*rest', name: 'Authorization', value: 'Bearer t', ...extra,
});
const ids = () => {
  let n = 0;
  return () => `n${++n}`;
};

describe('applyHeaderRules', () => {
  const facts = { method: 'GET', url: 'http://a.test/api/users/1' };
  it('sets a header on a matching call, replacing the page\'s own value whatever its case', () => {
    const r = applyHeaderRules([rule('a')], facts, { authorization: 'old', Accept: 'json' });
    expect(r.headers).toEqual({ Accept: 'json', authorization: 'Bearer t' });
    expect(r.changed).toEqual(['authorization']);
    const upper = applyHeaderRules([rule('a')], facts, { Authorization: 'old' });
    expect(upper.headers).toEqual({ authorization: 'Bearer t' });
  });
  it('an empty value removes the header', () => {
    const r = applyHeaderRules([rule('a', { name: 'X-Debug', value: '' })], facts, { 'x-debug': '1', a: 'b' });
    expect(r.headers).toEqual({ a: 'b' });
    expect(r.changed).toEqual(['x-debug']);
  });
  it('only rules that are on, and that match the URL and method, apply; later rules win', () => {
    const r = applyHeaderRules([
      rule('off', { enabled: false, name: 'X-Off', value: '1' }),
      rule('post', { method: 'POST', name: 'X-Post', value: '1' }),
      rule('other', { urlPattern: '/other/*rest', name: 'X-Other', value: '1' }),
      rule('first', { name: 'X-Team', value: 'red' }),
      rule('second', { name: 'x-team', value: 'blue' }),
    ], facts, {});
    expect(r.headers).toEqual({ 'x-team': 'blue' });
    expect(r.changed).toEqual(['x-team']);
  });
  it('a forbidden header is never set, even if a rule says so', () => {
    const r = applyHeaderRules([rule('c', { name: 'Cookie', value: 'a=b' })], facts, {});
    expect(r.headers).toEqual({});
    expect(r.changed).toEqual([]);
  });
  it('no rules: the same headers back, nothing changed', () => {
    expect(applyHeaderRules([], facts, { a: '1' })).toEqual({ headers: { a: '1' }, changed: [] });
  });
});

describe('rulesFor', () => {
  it('keeps the enabled rules that match the call', () => {
    const rules = [rule('a'), rule('b', { enabled: false }), rule('c', { urlPattern: '/x' }), rule('d', { method: 'POST' })];
    expect(rulesFor(rules, { method: 'GET', url: 'http://a.test/api/1' }).map((r) => r.id)).toEqual(['a']);
    expect(rulesFor(rules, { method: 'POST', url: 'http://a.test/api/1' }).map((r) => r.id)).toEqual(['a', 'd']);
  });
});

describe('forbiddenHeaderReason', () => {
  it('names the headers a page may not set', () => {
    for (const n of ['Cookie', 'host', 'Content-Length', 'Origin', 'Referer', 'Sec-Fetch-Mode', 'Proxy-Authorization', 'Connection']) {
      expect(forbiddenHeaderReason(n), n).toMatch(/^Browsers do not let pages set /);
    }
    expect(forbiddenHeaderReason('Authorization')).toBeNull();
    expect(forbiddenHeaderReason('X-Feature')).toBeNull();
  });
  it('an empty or invalid name is refused too', () => {
    expect(forbiddenHeaderReason('')).toBe('Type a header name');
    expect(forbiddenHeaderReason('bad name')).toBe('A header name has no spaces or symbols like : ( ) ,');
  });
});

describe('header rules travel with the project', () => {
  it('export and import keep them; files without them still load', () => {
    const p = newProject('p', 'http://a.test');
    p.headerRules = [rule('a'), rule('b', { value: '' })];
    const r = parseProjectFile(exportProject(p));
    expect(r.ok && r.project.headerRules).toEqual(p.headerRules);
    const q = newProject('q', 'http://a.test');
    const r2 = parseProjectFile(exportProject(q));
    expect(r2.ok && (r2.project.headerRules ?? [])).toEqual([]);
  });
  it('a bad rule rejects the file', () => {
    const p = newProject('p', 'http://a.test');
    p.headerRules = [{ ...rule('a'), name: 5 } as unknown as HeaderRule];
    expect(parseProjectFile(exportProject(p)).ok).toBe(false);
  });
  it('Add appends the file\'s rules with new ids; Replace takes the file\'s', () => {
    const target = newProject('t', 'http://a.test');
    target.headerRules = [rule('mine')];
    const incoming = newProject('i', 'http://b.test');
    incoming.headerRules = [rule('theirs', { name: 'X-B' })];
    const merged = mergeProject(target, incoming, ids());
    expect(merged.headerRules!.map((r) => r.name)).toEqual(['Authorization', 'X-B']);
    expect(merged.headerRules![1]!.id).not.toBe('theirs');
    expect(replaceProject(target, incoming).headerRules!.map((r) => r.name)).toEqual(['X-B']);
  });
});
